contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // Ensure newOwner is a valid address (not address(0)) as transferOwnership requires
        vm.assume(newOwner != address(0));
        // Initialize the contract to set up ownership
        c.initialize();
        // Record the current owner (should be the test contract, i.e., address(this))
        address originalOwner = c.owner();
        // Execute transferOwnership as the original owner
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);
        // Assert that the new owner is exactly the passed newOwner
        // The reference satisfies this for all inputs, the bug sets owner to address(0) for some newOwner
        assertTrue(c.owner() == newOwner);
    }
}

