pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newRoundImpl) public {
        // The fuzzer supplies any address; the owner is this test contract.
        // Owner needs to be set. Since c.initialize() was not called in setUp,
        // we call it here or in setUp? According to shape: only setUp given,
        // but we can call initialize here as owner is this contract initially (msg.sender).
        // Actually the reference C uses initializer modifier so need to call initialize first.
        c.initialize();
        // This test contract is the owner (msg.sender during initialize is this contract).
        // Now call updateRoundImplementation with the fuzzed address.
        c.updateRoundImplementation(payable(newRoundImpl));
        // In the reference, newRoundImpl must not be zero, so it will revert and state remains initial (zero).
        // In the mutant, the require is missing, so it will set roundImplementation to newRoundImpl.
        // The property: roundImplementation() always equals the argument if call succeeds, but reference ensures it never succeeds for zero.
        // Better rule: roundImplementation() is never zero after a successful call, but mutant allows zero.
        // However the exact rule from difference: "after a call, P.roundImplementation() != M.roundImplementation()"
        // Because for non-zero input both set it, they only differ when input is zero.
        // In reference, if input is zero, it reverts, so the value remains whatever it was before.
        // In mutant, it sets to zero. Therefore they differ.
        // We can assert that if the call does NOT revert, the stored value equals the input.
        // In reference, this is trivially true for all non-zero inputs (call succeeds, value equals input).
        // In mutant, for input zero, call succeeds, but stored value (zero) equals input (zero) as well, so that property holds for both!
        // Need a property that fails for mutant. Since reference reverts for zero, the expected behavior is that roundImplementation is never zero after any successful call. But mutant can set zero.
        // Actually after a revert in reference, state is unchanged. If we start with non-zero stored, then call with zero, reference keeps non-zero, mutant sets zero.
        // We can set up an initial non-zero roundImplementation via a first successful call with a non-zero address, then call again with zero. The reference will revert, mutant sets zero.
        // So property: After a successful call to updateRoundImplementation, if the call succeeds, the state is non-zero. Reference always satisfies because it only succeeds for non-zero inputs; mutant fails because it succeeds for zero input and state becomes zero.
        // But we need to fuzz the address and start from a known initial state. We can set up by first calling with a non-zero address, then call with the fuzzed address.
        // However the test function shape only has one call. But we can do multiple calls inside the test.
        // Let's first set roundImplementation to a non-zero by calling with a known non-zero address (but we can't hardcode a primitive deciding value? The rule says "Do NOT hard-code a primitive deciding value (an amount / id / actor)". So we cannot hard-code an initial address. However we can use address(this) or a newly deployed helper as initial non-zero address. That's allowed because it's not a deciding value that discriminates the bug; it's just setting up initial state. The deciding value is the fuzzed parameter newRoundImpl. So we can deploy a helper as an initial implementation.
        // Deploy a dummy contract to have a non-zero address.
        Dummy d = new Dummy();
        require(address(d) != address(0));
        // First set roundImplementation to that dummy address.
        c.updateRoundImplementation(payable(address(d)));
        // Now call with fuzzed newRoundImpl.
        bool success;
        try c.updateRoundImplementation(payable(newRoundImpl)) {
            success = true;
        } catch {
            success = false;
        }
        // Assert: If the call succeeded, the stored roundImplementation must NOT be zero.
        // This holds for reference: only succeeds for non-zero input, so stored is non-zero.
        // For mutant: succeeds for zero input, stored becomes zero -> property violated.
        if (success) {
            assertTrue(c.roundImplementation() != address(0));
        } else {
            // If call reverted, we don't check, but to make the assertion exactly one, we can assert that it either reverted or non-zero.
            // Actually the test must have exactly one assertTrue. So we need an expression that evaluates to true for reference always, false for mutant sometimes.
            // We can do: assertTrue( !success || c.roundImplementation() != address(0) );
            // Reference: For non-zero input, success = true, c.roundImplementation() = input != 0 -> expression true. For zero input, success = false -> expression true. So always true.
            // Mutant: For zero input, success = true, c.roundImplementation() = 0 -> expression false. So fails.
            assertTrue(!success || c.roundImplementation() != address(0));
        }
    }
}

contract Dummy {
    // Minimal helper just to have a non-zero address for initial state.
}

